# L1-1D (2026-10-13): independent re-verification of the local Cassels terms of S38-2 (Stage38_final v2 §4).
# Purpose: answer the open item "ALL_LOCAL_FORMULAS_FULLY_INDEPENDENTLY_CERTIFIED = NO" of audit round 1
# with an actual recomputation, not a text edit.
#
# Independence from the earlier implementation (L1 code, l1_ct.py):
#   - p-adic arithmetic: PARI t_PADIC (sqrt/issquare/valuation) instead of the hand-written Hensel code;
#   - Hilbert symbol: PARI hilbert(x,y,p) instead of the hand-written formula;
#   - local points: exactly the points specified in the proof (S, R+, R-, and the constructions at v=2,7,e,f),
#     not random samples. At split places S is also replaced by a genuine affine point with T=v^10 near S.
# Checked for every curve and every bad place {inf,2,3,7,41,d,e,f,p1,p2,q1,q2}:
#   (1) the point lies on D_{w1}: both quadrics vanish to v-adic precision >= 72 (N=80);
#   (2) the valuation claims of the proof (e.g. v_q(L2)=1 at R+, v3(L1)=3, v3(L2)=6 with L2 a 3-adic square,
#       L3 a non-square 3-adic unit, v_e(L3)=1, v_7(L3)=1, L2==L3 mod 16 at v=2);
#   (3) the local contribution sum_i h_v(L_i, beta'_i) equals the value stated in S38-2.
# Results:
#   367 curves (j<=12M, B=+1):  curves with any local discrepancy = 0; closed formula vs PARI ellrank: 0 mismatches.
#   2040 curves (12M<j<112M, B=+1): curves with any local discrepancy = 0.
# Sensitivity (mutation tests, 367 curves): each deliberate error is detected.
#   predicted c_41 changed           -> 180 curves flagged (= #curves with A=-1)
#   q-prediction uses b1 instead b2  -> 143 flagged
#   predicted c_e swapped            -> 367 flagged
#   near-S point perturbed (G2=2)    -> 367 flagged (point off the cover)
#   beta'_3 multiplied by 3          -> 367 flagged
# One bug in the first run of this checker: issquare() of an exact integer was tested over Q instead of Q_3
# (the contribution values already matched); fixed to issquare(x+O(3^N)).
# sha256(l1_audit.gp) = 5060eee32c99407f4d8ed4e807d9409bd80a2ab01e2d90cf5131b90bb4480dc3 (before adding this header)

##### FILE: l1_audit.gp
hb(x,y,v) = (1 - hilbert(x,y,v))/2;
ctr(Ls,bs,v) = (hb(Ls[1],bs[1],v)+hb(Ls[2],bs[2],v)+hb(Ls[3],bs[3],v))%2;
q4(a,p) = if(Mod(a,p)^((p-1)/4)==1,0,1);
lg(a,p) = if(kronecker(a,p)==1,0,1);
psq(x,v,N) = { my(z=x+O(v^N)); if(!issquare(z), error("nonsquare")); sqrt(z); }
rat(x) = truncate(x);

audit(u,p1,p2,q1,q2) =
{
  my(K=729,d=u,f=2*u+K,e=4*u+K,P=8*u^2-K^2,Q=-(8*u^2+8*K*u+K^2),t=(Q^2-P^2)/e,N=80);
  my(A=kronecker(d,p2), eps=(kronecker(p2,41)==-1), b1,b2,b3, bad=0, out=List());
  if(A==1, b1=p2; b2=p2*d^eps, b1=41*p1; b2=3*p1*d^eps); b3=b1*b2;
  my(bs=[b1,b2,b3]);
  my(Lf=(G1,G2,G3,T)->[-(t+1)*G2+(t-1)*G3+2*t*T, G1-Q*T, G1-P*T]);
  my(onD=(G1,G2,G3,T,v)->valuation(G1^2-P^2*T^2-e*G2^2,v)>=N-8 && valuation(G1^2-Q^2*T^2-e*G3^2,v)>=N-8);
  my(qs=[q1,q2], pred, c, L, G1,G2,G3,T, s, r, y, z, w, ok);
  pred=0; c=ctr([-2,1,1],bs,0); if(c!=pred, bad++; listput(out,["inf",c,pred]));
  foreach([d,41,p1,p2],v,
    s=psq(e,v,N);
    pred = if(v==p2 && A==1, q4(e,p2), if(v==p1 && A==-1, q4(e,p1), if(v==41 && A==-1, 1, 0)));
    c=ctr([-2,rat(s),rat(s)],bs,v);
    T=v^10; G2=1; G1=psq(e+P^2*T^2,v,N); G3=psq((G1^2-Q^2*T^2)/e,v,N);
    if(!onD(G1,G2,G3,T,v), bad++; listput(out,["notonD",v]));
    L=Lf(G1,G2,G3,T); my(c2=ctr(apply(rat,L),bs,v));
    if(c!=pred || c2!=pred, bad++; listput(out,["split",v,c,c2,pred])));
  foreach(qs,q,
    if(kronecker(d*f,q)==1,
      r=psq(t,q,N); if(rat(r)%q==1, r=-r);
      G1=-Q; G2=r; G3=0; T=1; pred=lg(b2,q);
      L=Lf(G1,G2,G3,T); ok = onD(G1,G2,G3,T,q) && valuation(L[1],q)==0 && valuation(L[2],q)==1 && valuation(L[3],q)==0,
      r=psq(-t,q,N); if((rat(r)+1)%q==0, r=-r);
      G1=-P; G2=0; G3=r; T=1; pred=0;
      L=Lf(G1,G2,G3,T); ok = onD(G1,G2,G3,T,q) && valuation(L[1],q)==0 && valuation(L[2],q)==0 && valuation(L[3],q)==0);
    c=ctr(apply(rat,L),bs,q); if(!ok || c!=pred, bad++; listput(out,["q",q,ok,c,pred])));
  r=psq(-t,3,N); if(valuation(r,3)!=3, error("v3"));
  G1=-P; G2=0; G3=r; T=1; L=Lf(G1,G2,G3,T);
  ok = onD(G1,G2,G3,T,3) && valuation(L[1],3)==3 && valuation(L[2],3)==6 && issquare(L[2]+O(3^N)) && valuation(L[3],3)==0 && !issquare(L[3]+O(3^N));
  pred = if(A==1,0,1); c=ctr(apply(rat,L),bs,3); if(!ok || c!=pred, bad++; listput(out,["3",ok,c,pred]));
  y = lift(Mod((1+t)/2,e)); G2=y; G3=psq(y^2-t,e,N); G1=psq(P^2+e*y^2,e,N); if(rat(G1-P)%e!=0, G1=-G1); T=1;
  L=Lf(G1,G2,G3,T); if(valuation(L[1],e)>0, G3=-G3; L=Lf(G1,G2,G3,T));
  ok = onD(G1,G2,G3,T,e) && valuation(L[1],e)==0 && valuation(L[2],e)==0 && valuation(L[3],e)==1;
  pred = if(A==1,0,1); c=ctr(apply(rat,L),bs,e); if(!ok || c!=pred, bad++; listput(out,["e",ok,c,pred]));
  z=psq(2,7,N); G2=P*z; G1=P*psq(1+e*z^2,7,N); G3=psq((G1^2-Q^2)/e,7,N); T=1;
  if(rat(G3+1)%7==0, G3=-G3); L=Lf(G1,G2,G3,T);
  ok = onD(G1,G2,G3,T,7) && valuation(L[1],7)==0 && valuation(L[2],7)==0 && valuation(L[3],7)==1;
  c=ctr(apply(rat,L),bs,7); if(!ok || c!=0, bad++; listput(out,["7",ok,c]));
  G2=1; while(kronecker(P^2+e*G2^2,f)!=1, G2++);
  G1=psq(P^2+e*G2^2,f,N); G3=psq(G2^2-t,f,N); if(rat(G3-G2)%f!=0, G3=-G3); T=1; L=Lf(G1,G2,G3,T);
  ok = onD(G1,G2,G3,T,f) && valuation(L[1],f)==0 && valuation(L[2],f)==0 && valuation(L[3],f)==0;
  c=ctr(apply(rat,L),bs,f); if(!ok || c!=0, bad++; listput(out,["f",ok,c]));
  G2=1; while(((1-e*G2^2)/4)%8!=1, G2+=2);
  my(s1=psq((1-e*G2^2)/4,2,N)); G1=1; T=2*s1/P; G3=psq((1-Q^2*T^2)/e,2,N); L=Lf(G1,G2,G3,T);
  ok = onD(G1,G2,G3,T,2) && valuation(L[2],2)==0 && valuation(L[3],2)==0 && valuation(L[2]-L[3],2)>=4;
  c=ctr(apply(rat,L),bs,2); if(!ok || c!=0, bad++; listput(out,["2",ok,c]));
  [bad, Vec(out)];
}

##### driver (python, cypari2): for each factor-form B=+1 row "j u p1 p2 q1 q2 B" call audit(u,p1,p2,q1,q2);
##### rows: ff.txt (L1-01, j<=12M) and scan12_112.txt (L1-18). Expected output: [0, []] for every curve.
